#include <stdio.h>

/* teste do desafio maior-caixa — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nao ha captura de stdout aqui. O teste declara o prototipo da
   caixa do aluno, chama-a e confere o VALOR devolvido com checa_int. Tres
   cenarios: o maior em segundo, o maior em primeiro e os dois iguais. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int maiorCaixa(int a, int b);

SM_TEST(o_maior_entre_3_e_9) {
    checa_int("o maior entre 3 e 9", maiorCaixa(3, 9), 9,
              "o maior e devolvido mesmo quando vem na segunda janela");
}

SM_TEST(o_maior_entre_9_e_3) {
    checa_int("o maior entre 9 e 3", maiorCaixa(9, 3), 9,
              "trocar a ordem dos argumentos nao muda o maior");
}

SM_TEST(os_dois_iguais) {
    checa_int("o maior entre 4 e 4", maiorCaixa(4, 4), 4,
              "com os dois valores iguais, o maior e esse mesmo valor");
}

solutionCode:
int maiorCaixa(int a, int b) {
    if (a >= b) {
        return a;
    }
    return b;
}
